const supportQRCode='data:image/png;base64,';
const supportDialog=document.createElement('dialog');supportDialog.id='supportDialog';supportDialog.setAttribute('aria-labelledby','supportTitle');supportDialog.innerHTML=`<form method="dialog"><button class="close" aria-label="关闭赞赏收款码">×</button></form><div class="eyebrow">THANKS FOR YOUR SUPPORT</div><h2 id="supportTitle">赏杯奶茶？</h2><p>自愿赞赏，不影响任何功能使用。</p><img class="support-qr" src="${supportQRCode}" alt="瞎折腾的支付宝赞赏收款码"><a class="support-original" href="https://github.com/xiazheteng8" target="_blank" rel="noopener noreferrer">前往作者 GitHub 主页核验 ↗</a><small class="support-thanks">支付宝扫一扫 · 感谢支持</small>`;document.body.append(supportDialog);
$('#supportOpen').onclick=event=>{event.preventDefault();event.stopPropagation();if(!supportDialog.open)supportDialog.showModal()};
supportDialog.addEventListener('pointerdown',event=>{if(event.target===supportDialog){const box=supportDialog.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)supportDialog.close()}});
